// Filter unprocessed rows (BD Created != yes).
// Track employer/maid names already seen (processed rows + current batch)
// to set SKIP_EMPLOYER / SKIP_MAID flags, preventing duplicate calendar events.
const allRows = $input.all().map((i, idx) => ({ ...i.json, _idx: idx }));

const processedEmployers = new Set(
  allRows
    .filter(r => String(r['BD Created'] || '').trim().toLowerCase() === 'yes')
    .map(r => String(r['Employer Name'] || '').trim().toUpperCase())
    .filter(n => n)
);
const processedMaids = new Set(
  allRows
    .filter(r => String(r['BD Created'] || '').trim().toLowerCase() === 'yes')
    .map(r => String(r['Maid Name'] || '').trim().toUpperCase())
    .filter(n => n)
);

const newRows = allRows.filter(row => {
  return String(row['BD Created'] || '').trim().toLowerCase() !== 'yes';
});

if (newRows.length === 0) return [];

const seenEmployers = new Set(processedEmployers);
const seenMaids = new Set(processedMaids);

return newRows.slice(0, 5).map(row => {
  const { _idx, ...rest } = row;
  const employerName = String(row['Employer Name'] || '').trim().toUpperCase();
  const maidName = String(row['Maid Name'] || '').trim().toUpperCase();
  const skipEmployer = employerName ? seenEmployers.has(employerName) : false;
  const skipMaid = maidName ? seenMaids.has(maidName) : false;
  if (employerName) seenEmployers.add(employerName);
  if (maidName) seenMaids.add(maidName);
  return { json: { ...rest, ROW_NUMBER: _idx + 2, SKIP_EMPLOYER: skipEmployer, SKIP_MAID: skipMaid } };
});

const row = $input.item.json;

const timestamp    = String(row['Timestamp'] || '').trim();
const rowNumber    = row.ROW_NUMBER || 0;
const skipEmployer = row.SKIP_EMPLOYER || false;
const skipMaid     = row.SKIP_MAID || false;
const employerName = String(row['Employer Name'] || '').trim();
const employerBirthdayRaw = String(row['Employer Birthday'] || '').trim();
const maidName = String(row['Maid Name'] || '').trim();
const maidBirthdayRaw = String(row['Maid Birthday'] || '').trim();

const monthMap = {
  jan: 1, january: 1, feb: 2, february: 2, mar: 3, march: 3,
  apr: 4, april: 4, may: 5, jun: 6, june: 6, jul: 7, july: 7,
  aug: 8, august: 8, sep: 9, sept: 9, september: 9,
  oct: 10, october: 10, nov: 11, november: 11, dec: 12, december: 12,
};

function parseDate(str) {
  if (!str) return null;
  str = str.trim();
  // Already ISO
  if (/^\d{4}-\d{2}-\d{2}$/.test(str)) return str;
  // DD Mon/Month YYYY  or  DD Mon/Month YY
  const textMatch = str.match(/^(\d{1,2})\s*[-]?\s*([a-zA-Z]+)\.?\s*[-]?\s*(\d{2,4})$/);
  if (textMatch) {
    const day = parseInt(textMatch[1]);
    const month = monthMap[textMatch[2].toLowerCase()];
    let year = parseInt(textMatch[3]);
    if (year < 100) year += 1900;
    if (month && day >= 1 && day <= 31) return year + '-' + String(month).padStart(2,'0') + '-' + String(day).padStart(2,'0');
  }
  // DD[-/. ]MM[-/. ]YYYY  (separators can have spaces around them)
  const numMatch = str.match(/^(\d{1,2})\s*[-\/\.]\s*(\d{1,2})\s*[-\/\.]\s*(\d{4})$/);
  if (numMatch) {
    const day = parseInt(numMatch[1]);
    const month = parseInt(numMatch[2]);
    const year = parseInt(numMatch[3]);
    if (month >= 1 && month <= 12 && day >= 1 && day <= 31)
      return year + '-' + String(month).padStart(2,'0') + '-' + String(day).padStart(2,'0');
  }
  // DD MM YYYY (space-separated numbers)
  const spaceMatch = str.match(/^(\d{1,2})\s+(\d{1,2})\s+(\d{4})$/);
  if (spaceMatch) {
    const day = parseInt(spaceMatch[1]);
    const month = parseInt(spaceMatch[2]);
    const year = parseInt(spaceMatch[3]);
    if (month >= 1 && month <= 12 && day >= 1 && day <= 31)
      return year + '-' + String(month).padStart(2,'0') + '-' + String(day).padStart(2,'0');
  }
  return null;
}

const pad = n => String(n).padStart(2, '0');

function nextBirthday(isoDate) {
  if (!isoDate) return { next: '', nextPlusOne: '' };
  const parts = isoDate.split('-');
  const bMonth = parseInt(parts[1]) - 1;
  const bDay = parseInt(parts[2]);
  const today = new Date();
  let next = new Date(today.getFullYear(), bMonth, bDay);
  if (next <= today) next = new Date(today.getFullYear() + 1, bMonth, bDay);
  const end = new Date(next);
  end.setDate(end.getDate() + 1);
  return {
    next:        next.getFullYear() + '-' + pad(next.getMonth() + 1) + '-' + pad(next.getDate()),
    nextPlusOne: end.getFullYear()  + '-' + pad(end.getMonth()  + 1) + '-' + pad(end.getDate()),
  };
}

const employerBD = nextBirthday(parseDate(employerBirthdayRaw));
const maidBD     = nextBirthday(parseDate(maidBirthdayRaw));

return {
  json: {
    TIMESTAMP:                       timestamp,
    ROW_NUMBER:                      rowNumber,
    SKIP_EMPLOYER:                   skipEmployer,
    SKIP_MAID:                       skipMaid,
    EMPLOYER_NAME:                   employerName.toUpperCase(),
    EMPLOYER_NEXT_BIRTHDAY:          employerBD.next,
    EMPLOYER_NEXT_BIRTHDAY_PLUS_ONE: employerBD.nextPlusOne,
    MAID_NAME:                       maidName.toUpperCase(),
    MAID_NEXT_BIRTHDAY:              maidBD.next,
    MAID_NEXT_BIRTHDAY_PLUS_ONE:     maidBD.nextPlusOne,
  }
};
